INSERT INTO `v1_8cf8a922806583f4b52a8ceff4938d59f1e2ed5388943471ea3c37fc5648dc82` VALUES (1.21875, 1.21875, 11506, 3, "チカのサマーピンバッジ", 1, "サマー衣装のチカがかわいく描かれたピンバッジ。限定バージョ\nンのデザインはサマーライブ参加の証。夏を満喫中のチカの表情\nが魅力的な一品。");
INSERT INTO `v1_8cf8a922806583f4b52a8ceff4938d59f1e2ed5388943471ea3c37fc5648dc82` VALUES (0.625, 0.75, 11601, 6, "ツムギのボトルキャップ", 1, "ツムギ・オンステージ！ツムギがキャップのステージでかわいく\nポーズを決めている。どこでも好きな場所に気軽に飾ることが可\n能。");
INSERT INTO `v1_8cf8a922806583f4b52a8ceff4938d59f1e2ed5388943471ea3c37fc5648dc82` VALUES (0.625, 0.75, 11602, 6, "ツムギのサマーボトルキャップ", 1, "サマー衣装のツムギが、キャップでオンステージ！涼しげな衣装を\nまとい、熱いステージを繰り広げた彼女の勇姿を思い出すことがで\nきる。");
INSERT INTO `v1_8cf8a922806583f4b52a8ceff4938d59f1e2ed5388943471ea3c37fc5648dc82` VALUES (0.625, 0.75, 11603, 6, "ノゾミのボトルキャップ", 1, "ノゾミ・オンステージ！ノゾミがキャップのステージでかわいく\nポーズを決めている。どこでも好きな場所に気軽に飾ることが可\n能。");
