INSERT INTO `v1_8cf8a922806583f4b52a8ceff4938d59f1e2ed5388943471ea3c37fc5648dc82` VALUES (0.890625, 0.8828125, 11701, 4, "ツムギのミニタペストリー", 1, "ツムギのキーホルダーサイズのタペストリー。どこにでも飾れる\nうえに、身につけてお出掛けもできてしまう万能な一品。");
